import { test, expect } from '@playwright/test';

test.describe('Copy to Clipboard Snackbar Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/copy-to-clipboard');
  });

  test('should display snackbar message after successfully copying text to clipboard', async ({ page }) => {
    // Locate and click the copy button using getByRole
    const copyButton = page.getByRole('button', { name: /copy to clipboard/i });
    await expect(copyButton).toBeVisible();
    await copyButton.click();

    // Wait for the snackbar to appear
    const snackbar = page.locator('[data-testid="snackbar-message"]');
    await expect(snackbar).toBeVisible();

    // Verify the snackbar contains the correct success message
    const messageText = page.getByText(/copied to clipboard/i);
    await expect(messageText).toBeVisible();

    // Verify the snackbar has a success styling (e.g, green background)
    await expect(snackbar).toHaveCSS('background-color', /green/);

    // Verify the snackbar has a dismiss button and it works
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();
    await dismissButton.click();

    // Verify the snackbar is dismissed
    await expect(snackbar).not.toBeVisible();
  });

  test('should handle copy failure and display error snackbar message', async ({ page }) => {
    // Intercept the copy API call and simulate failure
    await page.route('**/api/copy-text', route => {
      route.abort('failed');
    });

    // Locate and click the copy button using getByRole
    const copyButton = page.getByRole('button', { name: /copy to clipboard/i });
    await expect(copyButton).toBeVisible();
    await copyButton.click();

    // Wait for the error snackbar to appear
    const snackbar = page.locator('[data-testid="snackbar-message"]');
    await expect(snackbar).toBeVisible();

    // Verify the snackbar contains the correct error message
    const errorMessage = page.getByText(/failed to copy/i);
    await expect(errorMessage).toBeVisible();

    // Verify the snackbar has an error styling (e.g., red background)
    await expect(snackbar).toHaveCSS('background-color', /red/);

    // Verify the error message is displayed with appropriate styling
    await expect(snackbar).toContainText('Error');

    // Verify the error message has a dismiss button and it works
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();
    await dismissButton.click();

    // Verify the error snackbar is dismissed
    await expect(snackbar).not.toBeVisible();
  });
});
